#include <iostream>
#include <map>
#include <string>
using namespace std;

class FeatureFlags {
    map<string, bool> flags;
public:
    void enable(const string& name) { flags[name] = true; }
    void disable(const string& name) { flags[name] = false; }
    bool isEnabled(const string& name) { return flags[name]; }
    void listAll() {
        for (auto& [name, enabled] : flags)
            cout << name << ": " << (enabled ? "ON" : "OFF") << endl;
    }
};

int main() {
    FeatureFlags ff;
    ff.enable("dark_mode");
    ff.disable("beta_api");
    ff.enable("debug_logs");
    cout << "dark_mode: " << (ff.isEnabled("dark_mode") ? "ON" : "OFF") << endl;
    cout << "beta_api: " << (ff.isEnabled("beta_api") ? "ON" : "OFF") << endl;
    cout << "All flags:" << endl;
    ff.listAll();
    return 0;
}
